insert into public.words (slug, word, pronunciation, part_of_speech, definition, plain_english, examples, synonyms, difficulty, gre_frequency, etymology, etymology_status) values
('grandiloquent','grandiloquent','gran-DIL-uh-kwunt','adjective','Pompous or extravagant in language or style.','Using big, showy words to sound important.','{"His grandiloquent toast dragged on while the guests grew restless."}','{pompous,bombastic}',3,2,'Latin grandiloquus: grandis "great" + loqui "to speak".','established'),
('magniloquent','magniloquent','mag-NIL-uh-kwunt','adjective','Using high-flown or boastful language.','Talking in a grand, bragging way.','{"The magniloquent senator promised nothing less than a golden age."}','{grandiloquent,bombastic}',3,1,'Latin magniloquus: magnus "great" + loqui "to speak".','established'),
('obloquy','obloquy','OB-luh-kwee','noun','Strong public criticism or verbal abuse; the disgrace that results.','Harsh public blame, or the shame it brings.','{"The minister faced obloquy after the scandal broke."}','{censure,opprobrium}',3,2,'Late Latin obloquium "contradiction": ob- "against" + loqui "to speak".','established'),
('colloquy','colloquy','KOL-uh-kwee','noun','A formal conversation or dialogue.','A serious talk between people.','{"The colloquy between the two scholars lasted all afternoon."}','{dialogue,conference}',3,1,'Latin colloquium: com- "together" + loqui "to speak".','established'),
('elocution','elocution','el-uh-KYOO-shun','noun','The skill of clear and expressive speech.','The art of speaking clearly and well.','{"Years of elocution lessons gave her a crisp delivery."}','{diction,articulation}',3,1,'Latin elocutio: e- "out" + loqui (locut-) "to speak" + -ion.','established'),
('veracious','veracious','vuh-RAY-shus','adjective','Speaking or representing the truth; habitually truthful.','Honest; telling the truth.','{"Historians trusted the veracious diarist over the boastful general."}','{truthful,honest}',3,1,'Latin verax (verac-) "truthful", from verus "true", + -ious.','established'),
('aver','aver','uh-VUR','verb','To state or assert to be the case, firmly.','To say something is true with confidence.','{"The witness averred that she had seen the defendant leave."}','{assert,declare}',3,2,'Old French averer, from Latin ad- "to" + verus "true".','established'),
('perfidy','perfidy','PUR-fih-dee','noun','Deliberate breach of faith; treachery.','Betraying someone who trusted you.','{"The general''s perfidy cost the city its freedom."}','{treachery,betrayal}',3,2,'Latin perfidia: per- (here "away, to ruin") + fides "faith" + -ia.','established'),
('recreant','recreant','REK-ree-unt','adjective','Cowardly; unfaithful to a duty or cause.','Disloyal or cowardly.','{"The recreant knight fled the battlefield."}','{craven,disloyal}',3,1,'Old French recreant "yielding", from recroire: re- "back" + credere "to believe" (to take back one''s pledge).','established'),
('lucubration','lucubration','loo-kyoo-BRAY-shun','noun','Laborious study or writing, especially at night; a pedantic piece of writing.','Hard study late at night, or the overworked writing it produces.','{"His lucubrations filled six dense volumes."}','{study,treatise}',3,1,'Latin lucubrare "to work by lamplight", from lux (luc-) "light" + -ion.','established'),
('sophistry','sophistry','SOF-ih-stree','noun','Clever but misleading or false reasoning.','Arguments that sound smart but are deceptive.','{"The lawyer''s sophistry could not hide the weak evidence."}','{casuistry,speciousness}',3,3,'From Greek sophistes "wise man, teacher" (sophos "wise") + -ist + -ry.','established'),
('abjure','abjure','ab-JOOR','verb','To solemnly renounce a belief, claim, or cause.','To formally give something up or reject it.','{"He abjured his former allegiance under oath."}','{renounce,forswear}',3,2,'Latin abjurare: ab- "away" + jurare "to swear".','established'),
('adjure','adjure','uh-JOOR','verb','To urge or command someone solemnly, as if under oath.','To beg or order someone very seriously.','{"She adjured them to tell the whole truth."}','{implore,command}',3,1,'Latin adjurare: ad- "to" + jurare "to swear".','established'),
('perjury','perjury','PUR-juh-ree','noun','The offense of willfully lying under oath.','Lying after swearing to tell the truth.','{"The witness was charged with perjury."}','{"false testimony"}',3,2,'Latin perjurium: per- "through, i.e. violating" + jurare "to swear" + -ium.','established'),
('oppugn','oppugn','uh-PYOON','verb','To dispute the truth or validity of; to call into question.','To argue against or challenge something.','{"Critics oppugned the study''s methods."}','{challenge,dispute}',3,1,'Latin oppugnare: ob- "against" + pugnare "to fight".','established'),
('pugilist','pugilist','PYOO-juh-list','noun','A boxer, especially a professional.','A fighter who boxes.','{"The aging pugilist entered the ring one last time."}','{boxer,fighter}',3,1,'Latin pugil "boxer" (related to pugnus "fist") + -ist.','established'),
('avocation','avocation','av-oh-KAY-shun','noun','A hobby or minor occupation pursued for enjoyment.','Something you do on the side for fun, not your main job.','{"Birdwatching was the surgeon''s avocation."}','{hobby,pastime}',3,2,'Latin avocatio "a calling away": ab- "away" + vocare "to call" + -ion.','established'),
('equanimity','equanimity','ee-kwuh-NIM-ih-tee','noun','Mental calmness and composure, especially under stress.','Staying calm and steady when things get hard.','{"She received the bad news with equanimity."}','{composure,serenity}',3,3,'Latin aequanimitas: aequus "even" + animus "mind" + -ity.','established'),
('sequacious','sequacious','sih-KWAY-shus','adjective','Inclined to follow others uncritically; lacking independence of thought.','Tending to blindly follow others.','{"The sequacious committee endorsed every proposal of its chair."}','{servile,compliant}',3,1,'Latin sequax (sequac-) "following", from sequi "to follow", + -ious.','established'),
('neologism','neologism','nee-OL-uh-jiz-um','noun','A newly coined word or expression.','A brand-new word.','{"\"Selfie\" was once a neologism."}','{coinage}',3,2,'French néologisme: Greek neos "new" + logos "word" + -ism.','established'),
('philology','philology','fih-LOL-uh-jee','noun','The study of language in written historical sources.','The study of how languages and old texts developed.','{"Tolkien was a professor of philology."}','{linguistics}',3,1,'Greek philologia "love of learning/words": philos "loving" + logos "word" + -ia.','established')
on conflict (slug) do nothing;

with m(slug, pos, root, surface, contribution) as (values
('grandiloquent',1,'loqu','loqu','speak'),('grandiloquent',2,'ent-ant','-ent','"doing" → speaking grandly'),
('magniloquent',1,'loqu','loqu','speak'),('magniloquent',2,'ent-ant','-ent','"doing" → speaking greatly'),
('obloquy',0,'ob','ob-','against'),('obloquy',1,'loqu','loqu','speak'),('obloquy',2,'y','-y','noun: speaking against someone'),
('colloquy',0,'com-con','col-','together'),('colloquy',1,'loqu','loqu','speak'),('colloquy',2,'y','-y','noun: speaking together'),
('elocution',0,'e-ex','e-','out'),('elocution',1,'loqu','locut','speak'),('elocution',2,'tion','-ion','act of speaking out clearly'),
('veracious',0,'ver','ver','true'),('veracious',1,'acious','-acious','inclined to → truthful'),
('aver',0,'ad','a-','to'),('aver',1,'ver','ver','true → declare to be true'),
('perfidy',0,'per','per-','through/away → violating'),('perfidy',1,'fid','fid','faith'),('perfidy',2,'y','-y','noun: breaking faith'),
('recreant',0,'re','re-','back'),('recreant',1,'cred','cre','believe/pledge'),('recreant',2,'ent-ant','-ant','one who takes back a pledge'),
('lucubration',0,'luc','luc','light → working by lamplight'),('lucubration',1,'tion','-tion','noun: the act'),
('sophistry',0,'soph','soph','wise'),('sophistry',1,'ist','-ist','one who → sophist'),('sophistry',2,'y','-ry','practice of the sophists'),
('abjure',0,'ab','ab-','away'),('abjure',1,'jur','jure','swear → swear away'),
('adjure',0,'ad','ad-','to'),('adjure',1,'jur','jure','swear → bind by oath'),
('perjury',0,'per','per-','through → violating'),('perjury',1,'jur','jur','swear'),('perjury',2,'y','-y','noun: violating an oath'),
('oppugn',0,'ob','op-','against'),('oppugn',1,'pug','pugn','fight → fight against'),
('pugilist',0,'pug','pug','fist/fight'),('pugilist',1,'ist','-ist','one who fights'),
('avocation',0,'ab','a-','away'),('avocation',1,'voc','voc','call'),('avocation',2,'tion','-ation','noun: what calls you away from work'),
('equanimity',0,'equi','equ','even/equal → even mind'),('equanimity',1,'ity','-ity','state of'),
('sequacious',0,'sequ','sequ','follow'),('sequacious',1,'acious','-acious','inclined to follow'),
('neologism',0,'log','log','word'),('neologism',1,'ism','-ism','noun: a coinage (neo- = new)'),
('philology',0,'phil','phil','love'),('philology',1,'log','log','word'),('philology',2,'y','-y','study of: love of words')
)
insert into public.word_morphemes (word_id, root_id, position, surface, contribution)
select w.id, r.id, m.pos, m.surface, m.contribution
from m join public.words w on w.slug = m.slug join public.roots r on r.slug = m.root
where not exists (select 1 from public.word_morphemes x where x.word_id = w.id);